"""Conversation history persistence for Copilot v2.

Hosts the ``ThreadStore`` protocol plus an in-memory implementation (tests) and
a SQLite-backed implementation (production). Each stored record follows the
AG-UI Message shape and is keyed by ``thread_id``, so a turn can be rehydrated
verbatim from what was streamed to the client.

The SQLite store writes to the same database file as the v1 history store but in
its own ``thread_messages`` table. WAL mode plus conservative pragmas let the v1
and v2 writers share the file without tripping over each other's locks.
"""

from __future__ import annotations

import asyncio
import json
import os
import sqlite3
import uuid
from collections import defaultdict
from contextlib import contextmanager
from datetime import datetime, timezone
from typing import Any, Generator, Protocol, runtime_checkable


@runtime_checkable
class ThreadStore(Protocol):
    """Async protocol for thread message stores.

    Implementations persist AG-UI messages keyed by ``thread_id``. Each message
    follows the AG-UI Message shape and may carry any combination of ``id``,
    ``role``, ``content``, ``toolCalls``, and ``toolCallId``.
    """

    async def get_messages(self, thread_id: str) -> list[dict[str, Any]]:
        """Return all stored messages for the given thread in insertion order."""
        ...

    async def append_message(self, thread_id: str, message: dict[str, Any]) -> None:
        """Append a single message, assigning an id if absent."""
        ...

    async def append_messages(
        self, thread_id: str, messages: list[dict[str, Any]]
    ) -> None:
        """Append multiple messages to the thread in order."""
        ...

    async def clear_thread(self, thread_id: str) -> None:
        """Remove all messages for a thread."""
        ...


class InMemoryThreadStore:
    """In-memory message store keyed by ``thread_id``.

    Intentionally simple — use :class:`SQLiteThreadStore` for history that
    survives a restart. Handy as a test double and as a default when no durable
    store is configured.
    """

    def __init__(self) -> None:
        self._store: dict[str, list[dict[str, Any]]] = defaultdict(list)

    async def get_messages(self, thread_id: str) -> list[dict[str, Any]]:
        """Return a copy of all stored messages for the given thread."""
        return list(self._store[thread_id])

    async def append_message(self, thread_id: str, message: dict[str, Any]) -> None:
        """Append a single message to the thread, assigning an id if absent."""
        self._store[thread_id].append(_with_id(message))

    async def append_messages(
        self, thread_id: str, messages: list[dict[str, Any]]
    ) -> None:
        """Append multiple messages to the thread in order."""
        for message in messages:
            await self.append_message(thread_id, message)

    async def clear_thread(self, thread_id: str) -> None:
        """Remove all messages for a thread."""
        self._store.pop(thread_id, None)


class SQLiteThreadStore:
    """SQLite-backed thread message store.

    Each AG-UI message is stored as a JSON blob in a single ``thread_messages``
    table, which preserves arbitrary fields (``toolCalls``, ``toolCallId``, ...)
    without schema migrations. All synchronous DB work runs via
    ``asyncio.to_thread`` so the event loop is never blocked.

    The store shares its database file with the v1 history store, so every
    connection opts into WAL mode plus conservative pragmas (``synchronous`` and
    ``busy_timeout``) to keep concurrent v1/v2 writers from colliding.
    """

    _TABLE = "thread_messages"
    _BUSY_TIMEOUT_MS = 5000

    def __init__(self, db_path: str) -> None:
        # Fail fast on a missing/empty path: sqlite3.connect("") silently opens a
        # throwaway temp database and None raises an opaque TypeError deeper in,
        # so a misconfiguration would otherwise surface as "history vanished".
        if not db_path or not db_path.strip():
            raise ValueError(
                f"SQLiteThreadStore requires a non-empty database path; got "
                f"{db_path!r}."
            )
        self._db_path = db_path
        # A bare filename (no directory component) is valid — it resolves against
        # the cwd — so only create the parent directory when there is one.
        db_dir = os.path.dirname(db_path)
        if db_dir:
            os.makedirs(db_dir, exist_ok=True)
        self._init_db()

    def _init_db(self) -> None:
        with self._connection() as conn:
            conn.execute(
                f"""
                CREATE TABLE IF NOT EXISTS {self._TABLE} (
                    id           INTEGER PRIMARY KEY AUTOINCREMENT,
                    thread_id    TEXT    NOT NULL,
                    message_id   TEXT    NOT NULL,
                    role         TEXT    NOT NULL,
                    message_json TEXT    NOT NULL,
                    created_at   REAL    NOT NULL
                )
                """
            )
            conn.execute(
                f"""
                CREATE INDEX IF NOT EXISTS idx_thread_time
                ON {self._TABLE}(thread_id, created_at, id)
                """
            )
            conn.commit()

    @contextmanager
    def _connection(self) -> Generator[sqlite3.Connection, None, None]:
        """Open a connection with WAL mode and the conservative shared pragmas.

        ``journal_mode`` is a persistent database-level setting; ``synchronous``
        and ``busy_timeout`` are per-connection and so are re-applied each time.
        """
        conn = sqlite3.connect(self._db_path, timeout=self._BUSY_TIMEOUT_MS / 1000)
        try:
            conn.execute("PRAGMA journal_mode=WAL")
            conn.execute("PRAGMA synchronous=NORMAL")
            conn.execute(f"PRAGMA busy_timeout={self._BUSY_TIMEOUT_MS}")
            yield conn
        finally:
            conn.close()

    def _read(self, thread_id: str) -> list[dict[str, Any]]:
        with self._connection() as conn:
            cursor = conn.execute(
                f"""
                SELECT message_json
                FROM {self._TABLE}
                WHERE thread_id = ?
                ORDER BY created_at, id
                """,
                (thread_id,),
            )
            return [json.loads(row[0]) for row in cursor.fetchall()]

    def _write(self, thread_id: str, message: dict[str, Any]) -> None:
        self._write_many(thread_id, [message])

    def _write_many(self, thread_id: str, messages: list[dict[str, Any]]) -> None:
        """Insert every message for a turn in a single transaction.

        Writing the whole turn atomically means a mid-turn failure rolls back the
        earlier rows too, so the store never holds a truncated turn that no longer
        matches what was streamed to the client.
        """
        rows = [
            (
                thread_id,
                str(msg["id"]),
                str(msg.get("role", "")),
                json.dumps(msg, ensure_ascii=False),
                datetime.now(timezone.utc).timestamp(),
            )
            for msg in (_with_id(message) for message in messages)
        ]
        with self._connection() as conn:
            try:
                conn.executemany(
                    f"""
                    INSERT INTO {self._TABLE}
                        (thread_id, message_id, role, message_json, created_at)
                    VALUES (?, ?, ?, ?, ?)
                    """,
                    rows,
                )
                conn.commit()
            except Exception:
                conn.rollback()
                raise

    def _delete(self, thread_id: str) -> None:
        with self._connection() as conn:
            conn.execute(
                f"DELETE FROM {self._TABLE} WHERE thread_id = ?",
                (thread_id,),
            )
            conn.commit()

    def _handle_missing_table(self, exc: sqlite3.OperationalError) -> bool:
        """Recreate the table when a read/write hit a dropped/wiped database."""
        if "no such table" in str(exc).lower():
            self._init_db()
            return True
        return False

    async def get_messages(self, thread_id: str) -> list[dict[str, Any]]:
        """Return all stored messages for the given thread in insertion order."""
        try:
            return await asyncio.to_thread(self._read, thread_id)
        except sqlite3.OperationalError as exc:
            if self._handle_missing_table(exc):
                return []
            raise

    async def append_message(self, thread_id: str, message: dict[str, Any]) -> None:
        """Append a single message to the thread."""
        try:
            await asyncio.to_thread(self._write, thread_id, message)
        except sqlite3.OperationalError as exc:
            if self._handle_missing_table(exc):
                await asyncio.to_thread(self._write, thread_id, message)
                return
            raise

    async def append_messages(
        self, thread_id: str, messages: list[dict[str, Any]]
    ) -> None:
        """Append all messages for a turn atomically (single transaction)."""
        if not messages:
            return
        try:
            await asyncio.to_thread(self._write_many, thread_id, messages)
        except sqlite3.OperationalError as exc:
            if self._handle_missing_table(exc):
                await asyncio.to_thread(self._write_many, thread_id, messages)
                return
            raise

    async def clear_thread(self, thread_id: str) -> None:
        """Remove all messages for a thread."""
        try:
            await asyncio.to_thread(self._delete, thread_id)
        except sqlite3.OperationalError as exc:
            if self._handle_missing_table(exc):
                return
            raise


def _with_id(message: dict[str, Any]) -> dict[str, Any]:
    """Return a shallow copy of ``message`` with an ``id`` guaranteed to be set."""
    msg = dict(message)
    if not msg.get("id"):
        msg["id"] = uuid.uuid4().hex
    return msg
